  'product.feature.aiDesc': 'Rule-based clinical decision support running entirely in the browser. WHO/IMCI guideline-aligned. Suggests diagnoses, treatments, and lab orders — no internet required.',
  'product.feature.aiH1': 'WHO/IMCI guidelines',
  'product.feature.aiH2': '15+ priority diseases',
  'product.feature.aiH3': 'Offline AI inference',
  'product.feature.aiH4': 'Severity triage',
  'product.feature.aiTitle': 'AI-Powered Clinical Decision Support',
  'product.feature.configurableDesc': 'Flexible and configurable for any clinical area. Today TamamHealth is used in a wide variety of areas: from Primary Care for Outpatients; to Specialty Centers for NCD, MCH/ANC, HIV, TB, Malaria, and more; to large Hospital-based Inpatient care.',
  'product.feature.configurableH1': 'Primary Care & Outpatient',
  'product.feature.configurableH2': 'MCH / ANC / Immunization',
  'product.feature.configurableH3': 'NCD, HIV, TB, Malaria',
  'product.feature.configurableH4': 'Inpatient & Surgery',
  'product.feature.configurableTitle': 'Configurable for Any Clinical Program',
  'product.feature.documentationDesc': 'Triage and track your patients\' history. Write orders electronically. Create and customize all the forms your providers might need, for any clinical area. Non-developers can build new forms easily with the user-friendly Form Builder.',
  'product.feature.documentationH1': 'Electronic clinical notes',
  'product.feature.documentationH2': 'Customizable form builder',
  'product.feature.documentationH3': 'ICD-10/ICD-11 coding',
  'product.feature.documentationH4': 'Diagnosis & treatment tracking',
  'product.feature.documentationTitle': 'Clinical Documentation & Flexible Forms',
  'product.feature.interopDesc': 'The TamamHealth REST and FHIR-ready APIs enable integration with other end-user tools, such as ERP Systems, Lab Systems, DHIS2, and more; or, with National Health Exchanges.',
  'product.feature.interopH1': 'DHIS2 automated export',
  'product.feature.interopH2': 'REST API',
  'product.feature.interopH3': 'FHIR-ready architecture',
  'product.feature.interopH4': 'National system integration',
  'product.feature.interopTitle': 'Interoperable Locally and Nationally',
  'product.feature.privilegesDesc': 'Role-based access and deeper permissions granularity, such as by location or data types. Audit logging enables follow up on actions taken. 11+ distinct user roles from CHW to Ministry admin.',
  'product.feature.privilegesH1': '11+ user roles (RBAC)',
  'product.feature.privilegesH2': 'Location-based access',
  'product.feature.privilegesH3': 'Audit logging',
  'product.feature.privilegesH4': 'Session management',
  'product.feature.privilegesTitle': 'Privileges & User Management',
  'product.feature.registrationDesc': 'Manage your patient lists and bookings in one location or across multiple sites. Connect your registration to national patient databases. Handle bills, inventory, labs, and dispensing directly or through integration.',
  'product.feature.registrationH1': 'Patient registration & search',
  'product.feature.registrationH2': 'Appointment scheduling',
  'product.feature.registrationH3': 'Queue management',
  'product.feature.registrationH4': 'Billing & stock management',
  'product.feature.registrationTitle': 'Registration, Appointments, Queues & Billing',
  'product.feature.reportingDesc': 'Track and analyze clinical data: See your impact, report to stakeholders, and monitor key metrics. Generate IDSR reports, MCH analytics, and donor-ready outputs.',
  'product.feature.reportingH1': 'IDSR weekly reports',
  'product.feature.reportingH2': 'MCH analytics dashboard',
  'product.feature.reportingH3': 'Custom report builder',
  'product.feature.reportingH4': 'Donor-ready exports',
  'product.feature.reportingTitle': 'Clinical Data Reporting & Exports',
  'product.feature.translationDesc': 'TamamHealth has configurable translation tools so your team can set up the languages your users need — including supporting multiple different languages at once, and Right-to-Left language support.',
  'product.feature.translationH1': 'Multi-language interface',
  'product.feature.translationH2': '60+ South Sudan languages',
  'product.feature.translationH3': 'RTL support',
  'product.feature.translationH4': 'Icon-driven for low-literacy',
  'product.feature.translationTitle': 'Language Translation',
  'product.features.desc': 'Some of the key features of TamamHealth include:',
  'product.features.eyebrow': 'Features',
  'product.features.moreCount': '90 major features',
  'product.features.morePrefix': 'There are more than',
  'product.features.moreSuffix': 'in the starter TamamHealth EMR, and many more that can be optionally added on — or, you can add your own features!',
  'product.features.takeTour': 'Take a Quick Tour',
  'product.features.title': 'TamamHealth EMR Features',
